changeSet.sql:
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'redgate') THEN
    EXECUTE 'CREATE SCHEMA redgate AUTHORIZATION ' || current_user;
  END IF;
END$$;

CREATE TABLE IF NOT EXISTS redgate.feedback_audit (
  audit_id    BIGSERIAL PRIMARY KEY,
  customer_id INTEGER,
  note        VARCHAR(200),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
